import{_ as t,o as i,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Zendure HA troubleshooting","description":"Troubleshooting connection issues with the Zendure Home Assistant integration.","frontmatter":{"title":"Zendure HA troubleshooting","description":"Troubleshooting connection issues with the Zendure Home Assistant integration."},"headers":[],"relativePath":"en/collection/zendure-ha/fehlersuche.md","filePath":"en/collection/zendure-ha/fehlersuche.md","lastUpdated":1793123358000}'),n={name:"en/collection/zendure-ha/fehlersuche.md"};function o(l,e,d,s,h,c){return i(),a("div",null,[...e[0]||(e[0]=[r('<p><a id="zendure-ha-troubleshooting"></a><a id="current-focus"></a></p><h1 id="fehlersuche" tabindex="-1">Troubleshooting <a class="header-anchor" href="#fehlersuche" aria-label="Permalink to &quot;Troubleshooting {#fehlersuche}&quot;">​</a></h1><h2 id="grundcheck" tabindex="-1">Basic check <a class="header-anchor" href="#grundcheck" aria-label="Permalink to &quot;Basic check {#grundcheck}&quot;">​</a></h2><ol><li>Update integration to the current version.</li><li>Restart Home Assistant.</li><li>Check if the Zendure app token comes from the main account.</li><li>Check if devices are visible in the Zendure app.</li><li>Enable debug logging for Zendure integration.</li><li>For local MQTT: Check broker address, user, password, WiFi SSID and WiFi password.</li></ol><h2 id="haufige-fehlermeldungen" tabindex="-1">Common error messages <a class="header-anchor" href="#haufige-fehlermeldungen" aria-label="Permalink to &quot;Common error messages {#haufige-fehlermeldungen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Meaning/Measure</th></tr></thead><tbody><tr><td>Token invalid</td><td>Copy tokens again from Zendure app</td></tr><tr><td>No devices found</td><td>Check wrong Zendure account or region</td></tr><tr><td>No MQTT server returned</td><td>Check local or cloud MQTT in Zendure app</td></tr><tr><td>No backup group</td><td>Set Fuse Group</td></tr><tr><td>HEMS</td><td>Device is influenced by HEMS and cannot be freely controlled by the manager</td></tr></tbody></table><h2 id="hyper2000-legacy-gerate" tabindex="-1">Hyper2000/Legacy devices <a class="header-anchor" href="#hyper2000-legacy-gerate" aria-label="Permalink to &quot;Hyper2000/Legacy devices {#hyper2000-legacy-gerate}&quot;">​</a></h2><p>If you have connection problems, the original wiki recommends:</p><ol><li>Enable debug logging.</li><li>Delete integration entry.</li><li>Restart device.</li><li>Update integration.</li><li>Add new integration with Zendure app token.</li><li>Enable MQTT logging.</li><li>Set up local MQTT with all fields.</li><li>First test <code>cloud</code> as the connection mode.</li><li>Set Fuse Group.</li><li>Check whether the device has a Bluetooth MAC address.</li><li>Wait at least 10 minutes because updates via Bluetooth can be delayed.</li></ol><h2 id="wenn-das-gerat-nicht-reagiert" tabindex="-1">If the device is not responding <a class="header-anchor" href="#wenn-das-gerat-nicht-reagiert" aria-label="Permalink to &quot;If the device is not responding {#wenn-das-gerat-nicht-reagiert}&quot;">​</a></h2><ul><li>Select operating mode <code>Manuelle Leistungsregelung</code>.</li><li>Change <code>Manuelle Leistung</code> as a test, for example 300 W and then 400 W.</li><li>Then test <code>Smarte Leistungsregelung</code>.</li><li>If there is no response, save the complete debug log.</li></ul><p>Original wiki:</p><ul><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Troubleshooting" target="_blank" rel="noreferrer">Troubleshooting</a></li></ul>',13)])])}const p=t(n,[["render",o]]);export{g as __pageData,p as default};
